INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Software > Auswahl > Anwendungen > Spezialisierte Software
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können spezialisierte Softwarelösungen unabhängig von den spezifischen Anforderungen der Branche ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Branchenanforderungen bestimmen Funktionalität"}, {"text": "Ja", "correct": false, "because": "Ohne Anpassung ineffektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl spezialisierter Software immer die Kompatibilität mit bestehenden Systemen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Integration mit Hardware und Software ist essenziell"}, {"text": "Nein", "correct": false, "because": "Kompatibilität ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Benutzerfreundlichkeit bei spezialisierter Software weniger wichtig als bei Standardsoftware?', 2, '[{"text": "Nein", "correct": true, "because": "Benutzerfreundlichkeit steigert Effizienz auch bei Spezialsoftware"}, {"text": "Ja", "correct": false, "because": "Usability bleibt entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können spezialisierte Softwarelösungen ohne Rücksicht auf die Kosten ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Budget beeinflusst Entscheidung"}, {"text": "Ja", "correct": false, "because": "Kosten sind relevant"}]'),
('00000000-0000-0000-0000-0000-000000000000', 'Sind spezialisierte Softwarelösungen immer teurer als Standardsoftware?', 2, '[{"text": "Ja", "correct": true, "because": "Spezialisierung erhöht oft Entwicklungskosten"}, {"text": "Nein", "correct": false, "because": "Preisunterschied ist üblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl spezialisierter Software am wichtigsten?', 3, '[{"text": "Branchenspezifische Anforderungen", "correct": true, "because": "Bestimmen Funktionalität und Nutzen"}, {"text": "Kosten", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Markenbekanntheit", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von spezialisierter Software wird häufig in der Architektur eingesetzt?', 2, '[{"text": "CAD-Software", "correct": true, "because": "Für technische Zeichnungen geeignet"}, {"text": "ERP-System", "correct": false, "because": "Für Unternehmensplanung"}, {"text": "CRM-Software", "correct": false, "because": "Für Kundenmanagement"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist entscheidend für die Auswahl spezialisierter Software in der Medizin?', 2, '[{"text": "Datensicherheit", "correct": true, "because": "Schutz sensibler Patientendaten"}, {"text": "Druckgeschwindigkeit", "correct": false, "because": "Nicht primär"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion erfüllt spezialisierte Software wie ERP-Systeme?', 3, '[{"text": "Ressourcenplanung", "correct": true, "because": "Optimiert Unternehmensprozesse"}, {"text": "Fotobearbeitung", "correct": false, "because": "Andere Softwarekategorie"}, {"text": "Netzwerkdiagnose", "correct": false, "because": "Nicht ERP-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil spezialisierter Software?', 2, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Auf spezifische Aufgaben zugeschnitten"}, {"text": "Geringere Kosten", "correct": false, "because": "Oft teurer"}, {"text": "Einfache Installation", "correct": false, "because": "Nicht primär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl spezialisierter Software?', 4, '[{"text": "Branchenanforderungen", "correct": true, "because": "Definiert Funktionalität"}, {"text": "Kompatibilität", "correct": true, "because": "Integration mit Systemen"}, {"text": "Benutzerfreundlichkeit", "correct": true, "because": "Erleichtert Nutzung"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gehören zu spezialisierter Software?', 3, '[{"text": "CAD-Software", "correct": true, "because": "Für Design und Technik"}, {"text": "ERP-Systeme", "correct": true, "because": "Für Unternehmensplanung"}, {"text": "Medizinische Bildgebung", "correct": true, "because": "Für Gesundheitswesen"}, {"text": "Textverarbeitung", "correct": false, "because": "Standardsoftware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl spezialisierter Software auftreten?', 3, '[{"text": "Hohe Kosten", "correct": true, "because": "Spezialisierung ist teuer"}, {"text": "Inkompatibilität", "correct": true, "because": "Passt nicht zu bestehenden Systemen"}, {"text": "Komplexität", "correct": true, "because": "Schwierige Bedienung"}, {"text": "Geringe Lautstärke", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien machen spezialisierte Software effektiv?', 4, '[{"text": "Funktionalität", "correct": true, "because": "Erfüllt spezifische Aufgaben"}, {"text": "Support", "correct": true, "because": "Hilft bei Problemen"}, {"text": "Skalierbarkeit", "correct": true, "because": "Passt sich Wachstum an"}, {"text": "Minimale Größe", "correct": false, "because": "Nicht primär entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branchen nutzen spezialisierte Software häufig?', 3, '[{"text": "Medizin", "correct": true, "because": "Für Diagnose und Verwaltung"}, {"text": "Bauwesen", "correct": true, "because": "Für Planung und Design"}, {"text": "Logistik", "correct": true, "because": "Für Transportmanagement"}, {"text": "Textverarbeitung", "correct": false, "because": "Allgemeine Nutzung"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Spezialisierte Software muss branchenspezifisch sein. b) Sie ist immer günstiger als Standardsoftware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Branchenspezifisch ja, teurer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CAD-Software ist ein Beispiel für spezialisierte Software. b) Benutzerfreundlichkeit ist bei Spezialsoftware irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CAD ja, Usability wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Spezialisierte Software erfordert oft spezifische Hardware. b) Sie ist für alle Branchen gleich geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ja, branchenspezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) ERP-Systeme sind spezialisierte Software für Unternehmen. b) Kosten spielen bei der Auswahl keine Rolle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ERP ja, Kosten relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Spezialisierte Software steigert Effizienz in bestimmten Bereichen. b) Sie ist immer einfach zu bedienen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ja, Bedienung komplex"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

